using namespace cg3::cgal::internal;

Polygon_2 poly1;
for (const auto& p : P1.outer) {
    poly1.push_back(Point_2(p.x(), p.y()));
}
for (const auto& hole : P1.inner) {
    Polygon_2 h;
    for (const auto& p : hole) {
        h.push_back(Point_2(p.x(), p.y()));
    }
    poly1.holes().push_back(h);
}

Polygon_2 poly2;
for (const auto& p : P2.outer) {
    poly2.push_back(Point_2(p.x(), p.y()));
}
for (const auto& hole : P2.inner) {
    Polygon_2 h;
    for (const auto& p : hole) {
        h.push_back(Point_2(p.x(), p.y()));
    }
    poly2.holes().push_back(h);
}

Pwh_list_2 result_list;
CGAL::Boolean_set_operations_2<Kernel>::intersection(poly1, poly2, result_list);

std::vector<PolygonWithHoles2d> result;
for (const auto& pwh : result_list) {
    PolygonWithHoles2d res_poly;

    // Extract outer boundary
    for (auto it = pwh.outer().vertices_begin(); it != pwh.outer().vertices_end(); ++it) {
        double x, y;
        getCoordinates(*it, x, y);
        res_poly.outer.push_back(Point2d(x, y));
    }

    // Extract holes
    for (const auto& hole : pwh.holes()) {
        std::vector<Point2d> res_hole;
        for (auto it = hole.vertices_begin(); it != hole.vertices_end(); ++it) {
            double x, y;
            getCoordinates(*it, x, y);
            res_hole.push_back(Point2d(x, y));
        }
        res_poly.inner.push_back(res_hole);
    }
    result.push_back(res_poly);
}

return result;

